// remove duplicate Bayan-Olgii  
const aimagsClean = aimags.filter(a => !a.duplicate);

function renderAimagCard(a) {
  const img = getAimagImg(a);
  return `
    <div class="aimag-card" onclick="navigate('aimag-detail', ${a.id})">
      <div class="aimag-card-img-wrap">
        <img src="${img.u}" loading="lazy" alt="${a.name}" onerror="this.remove()">
        <span class="aimag-card-emoji-over">${a.emoji}</span>
        <span class="card-img-credit">${img.s==="Wikipedia CC"?"© Wikipedia CC":"Unsplash"}</span>
      </div>
      <div class="aimag-card-name">${a.name}</div>
      <div class="aimag-card-region">${a.region} бүс · ${a.capital}</div>
      <div class="aimag-card-stats">9 онцлох газар · 9 болзоо</div>
    </div>`;
}

function renderAimags() {
  const filtered = currentRegion === "all" ? aimagsClean : aimagsClean.filter(a => a.region === currentRegion);
  document.getElementById("aimagsGrid").innerHTML = filtered.map(renderAimagCard).join("");
}

function renderAimagDetail(id) {
  const a = aimagsClean.find(x => x.id == id);
  if(!a) return navigate('aimags');
  currentAimagId = id;
  
  const aiImg = getAimagImg(a);
  document.getElementById("aimagDetail").innerHTML = `
    <div class="aimag-detail">
      <div class="aimag-header" style="position:relative; overflow:hidden;">
        <img src="${aiImg.u}" loading="lazy" alt="${a.name}"
          style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0.22;z-index:0;"
          onerror="this.remove()">
        <div style="position:relative;z-index:1;">
          <div style="font-size: 56px; margin-bottom: 8px;">${a.emoji}</div>
          <h1>${a.name} аймаг</h1>
          <div class="meta">${a.region} бүс · Төв нь ${a.capital} · 9 онцлох газар + 9 болзоо</div>
          <div style="font-size:10px; opacity:0.6; margin-top:6px;">📸 ${aiImg.s}</div>
        </div>
      </div>
      <div class="aimag-section">
        <h3>📜 Түүхэн мэдээлэл</h3>
        <p class="history-text">${a.history}</p>
      </div>
      <div class="aimag-section">
        <h3>✨ ${a.name}-н онцлох 9 газар</h3>
        <p style="color:var(--text-light); font-size:13px; margin-bottom:12px;">💡 Газар бүр дээр дарж нэрийн гарал, түүх, юу үзэхийг харна уу</p>
        <div class="wonders-grid">
          ${a.wonders.map((w, wi) => {
            const wt = getWonderType(a.id, wi);
            const wImg = wonderTypeImgDB[wt];
            const imgHtml = wImg
              ? `<img src="${wImg.u}" loading="lazy" alt="${w.name}" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0;" onerror="this.remove()"><div style="position:absolute;inset:0;background:rgba(0,0,0,0.25);z-index:1;"></div>`
              : "";
            return `
            <div class="wonder-item" onclick="openWonderModal(${a.id}, ${wi})">
              <div class="wonder-visual ${wt}" style="position:relative;overflow:hidden;">
                ${imgHtml}
                <span class="wonder-visual-emoji" style="position:relative;z-index:2;">${w.emoji}</span>
              </div>
              <div class="wonder-name">${w.name}</div>
              <div class="wonder-desc">${w.desc}</div>
              <div class="wonder-more">Дэлгэрэнгүй →</div>
            </div>`;
          }).join("")}
        </div>
      </div>
      <div class="aimag-section">
        <h3>💕 ${a.name}-д хийх 9 болзоо</h3>
        <div class="cards-grid" style="margin-top: 12px;">
          ${a.dates.map((d, idx) => `
            <div class="card" onclick="openAimagDateModal(${a.id}, ${idx})">
              <div class="card-image" style="background: ${getColor(idx)}">${d.emoji}</div>
              <div class="card-body">
                <div class="card-location">📍 ${a.name}</div>
                <div class="card-title">${d.title}</div>
                <div class="card-desc">${d.desc}</div>
                <div class="card-feeling">💝 ${d.feeling.substring(0, 80)}...</div>
                <div class="card-footer">
                  <span class="card-price">${d.price}</span>
                  <span class="card-likes">🤍 ${Math.floor(Math.random()*500)+100}</span>
                </div>
              </div>
            </div>
          `).join("")}
        </div>
      </div>
      ${renderSumSection(a)}
    </div>
  `;
}

// Гайхамшгийн зургийн төрөл авах
function getWonderType(aimagId, wonderIdx) {
  try {
    const wd = wonderDetails[aimagId];
    if(wd && wd[wonderIdx]) return wd[wonderIdx].type || "nature";
  } catch(e) {}
  return "nature";
}

// Гайхамшгийн дэлгэрэнгүй modal
function openWonderModal(aimagId, wonderIdx) {
  const a = aimagsClean.find(x => x.id === aimagId);
  if(!a) return;
  const w = a.wonders[wonderIdx];
  const wd = (wonderDetails[aimagId] && wonderDetails[aimagId][wonderIdx]) || {};
  const type = wd.type || "nature";

  document.getElementById("modalContent").innerHTML = `
    <div class="modal-header">
      <h2 style="font-size: 22px;">${w.emoji} ${w.name}</h2>
      <button type="button" class="modal-close" onclick="closeModal()">×</button>
    </div>
    <div class="modal-body">
      ${(wonderTypeImgDB[type]) ? (() => {
        const wi = wonderTypeImgDB[type];
        return `<div class="wonder-modal-visual ${type}" style="position:relative;overflow:hidden;">
          <img src="${wi.u}" loading="lazy" alt="${w.name}"
            style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0;"
            onerror="this.remove()">
          <div style="position:absolute;inset:0;background:rgba(0,0,0,0.2);z-index:1;"></div>
          <span class="emoji" style="position:relative;z-index:2;">${w.emoji}</span>
          <span class="card-img-credit" style="z-index:3;">${wi.s==="Wikipedia CC"?"© Wikipedia CC":"Unsplash"}</span>
        </div>`;
      })() : `<div class="wonder-modal-visual ${type}"><span class="emoji">${w.emoji}</span></div>`}
      <div class="modal-meta" style="margin-bottom:16px;">
        <div class="modal-meta-item">📍 <strong>${a.name} аймаг</strong></div>
        <div class="modal-meta-item">🏷 <strong>${typeLabel(type)}</strong></div>
      </div>

      ${mapEmbedHtml(`${w.name}, ${a.name} аймаг`)}

      <div class="wonder-detail-section">
        <div class="label">🔤 Нэрийн гарал (яагаад ингэж нэрлэсэн)</div>
        <div class="text">${wd.origin || w.desc}</div>
      </div>

      <div class="wonder-detail-section">
        <div class="label">📜 Түүх</div>
        <div class="text">${wd.history || 'Орон нутгийн онцлох газар.'}</div>
      </div>

      <div class="wonder-detail-section">
        <div class="label">👁 Хүн очоод юу үзэх вэ</div>
        <div class="text">${wd.see || w.desc}</div>
      </div>
    </div>
  `;
  document.getElementById("modal").classList.add("show");
}

function typeLabel(type) {
  const labels = {
    lake:"Нуур", mountain:"Уул", desert:"Цөл/Элс", volcano:"Галт уул",
    cave:"Агуй", temple:"Хийд/Сүм", waterfall:"Хүрхрээ", rock:"Хадан тогтоц",
    ruins:"Эртний туурь", steppe:"Тал хээр", canyon:"Хавцал", river:"Гол",
    spring:"Рашаан", nomad:"Нүүдэлчид", historic:"Түүхэн дурсгал", nature:"Байгаль"
  };
  return labels[type] || "Байгаль";
}

// Аймгийн id-г aimagSums key рүү хөрвүүлэх
const aimagIdToKey = {
  1:"arkhangai", 2:"bayan-ulgii", 3:"bayankhongor", 4:"govisumber", 5:"bulgan",
  6:"govi-altai", 7:"darkhan-uul", 8:"dornogovi", 9:"dornod", 10:"dundgovi",
  11:"zavkhan", 12:"orkhon", 13:"uvurkhangai", 14:"umnugovi", 15:"sukhbaatar",
  16:"selenge", 17:"tuv", 18:"uvs", 19:"khovd", 20:"khuvsgul", 21:"khentii"
};

function renderSumSection(a) {
  const key = aimagIdToKey[a.id];
  if(!key || !aimagSums[key]) return "";
  const sumData = aimagSums[key];
  const sums = sumData.sums;
  return `
    <div class="aimag-section">
      <h3>🏘 ${a.name} аймгийн ${sums.length} сум</h3>
      <div class="sum-count-info">
        💡 Сум бүр дээр дарж түүх, очиж үзэх газар, болзооны санааг харна уу. Монгол улс нийт 330 сумтай.
      </div>
      <input type="text" class="sum-search" placeholder="🔍 Сум хайх..." oninput="filterSums(this.value)" />
      <div class="sum-list" id="sumList">
        ${sums.map((s, idx) => `
          <div class="sum-item" data-sumname="${s.name.toLowerCase()}" data-sumquery="${escapeHtml(s.name + ' сум, ' + a.name + ' аймаг')}" onclick="toggleSum(this)">
            <div class="sum-item-head">
              <span class="sum-item-name">${idx+1}. ${s.name}${s.isCenter ? ' сум' : ' сум'}</span>
              <div style="display:flex; align-items:center; gap:8px;">
                <span class="sum-eth-badge">👥 ${(s.ethnicity || 'Халх').split(',')[0].split('(')[0].trim()}</span>
                ${s.isCenter ? '<span class="sum-item-badge">Аймгийн төв</span>' : ''}
                <span class="sum-item-toggle">⌄</span>
              </div>
            </div>
            <div class="sum-item-body">
              <div class="sum-detail-row">
                <div class="sum-detail-label">👨‍👩‍👧 Ястан / Угсаатан</div>
                <div class="sum-detail-text">${s.ethnicity || 'Халх'}</div>
              </div>
              <div class="sum-detail-row">
                <div class="sum-detail-label">📜 Түүх</div>
                <div class="sum-detail-text">${s.history}</div>
              </div>
              <div class="sum-detail-row">
                <div class="sum-detail-label">📍 Очиж үзэх газар</div>
                <div class="sum-detail-text">${s.place}</div>
              </div>
              <div class="sum-detail-row">
                <div class="sum-detail-label">💕 Болзооны санаа</div>
                <div class="sum-detail-text">${s.date}</div>
              </div>
              <div class="sum-map-slot"></div>
            </div>
          </div>
        `).join("")}
      </div>
    </div>
  `;
}

function toggleSum(el) {
  el.classList.toggle("open");
  if (el.classList.contains("open")) {
    const slot = el.querySelector(".sum-map-slot");
    if (slot && !slot.dataset.loaded) {
      slot.dataset.loaded = "1";
      slot.innerHTML = mapEmbedHtml(el.dataset.sumquery);
    }
  }
}

function filterSums(query) {
  const q = query.toLowerCase();
  document.querySelectorAll("#sumList .sum-item").forEach(item => {
    const name = item.dataset.sumname || "";
    item.style.display = name.includes(q) ? "" : "none";
  });
}

function openAimagDateModal(aimagId, dateIdx) {
  const a = aimagsClean.find(x => x.id == aimagId);
  const d = a.dates[dateIdx];
  const aiImg = getAimagImg(a);
  document.getElementById("modalContent").innerHTML = `
    <div class="modal-header">
      <h2 style="font-size: 20px;">${d.emoji} ${d.title}</h2>
      <button class="modal-close" onclick="closeModal()" type="button">×</button>
    </div>
    <div class="modal-body">
      <div class="modal-image" style="background:linear-gradient(135deg,var(--primary),var(--primary-light));position:relative;overflow:hidden;padding:0;">
        <img src="${aiImg.u}" loading="lazy" alt="${a.name} аймаг" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;" onerror="this.remove()">
        <div style="position:absolute;inset:0;background:rgba(0,0,0,0.25);"></div>
        <span style="position:relative;z-index:1;font-size:56px;filter:drop-shadow(0 2px 8px rgba(0,0,0,0.5));">${d.emoji}</span>
        <span class="card-img-credit" style="z-index:2;">📍 ${a.name} · ${aiImg.s}</span>
      </div>
      <div class="modal-meta">
        <div class="modal-meta-item">📍 <strong>${a.name} аймаг</strong></div>
        <div class="modal-meta-item">💸 <strong>${d.price}</strong></div>
      </div>
      ${mapEmbedHtml(`${d.title}, ${a.name} аймаг`)}
      <p style="margin-bottom: 16px; line-height: 1.7;">${d.desc}</p>
      <div class="feeling-box">
        <h4>💝 Энэ болзоонд танд төрөх мэдрэмж:</h4>
        <p>${d.feeling}</p>
      </div>
      <div style="display:flex; gap:8px; flex-wrap:wrap;">
        <button class="btn btn-primary" style="flex:1" type="button" onclick="openBookingModal(null,'${d.title.replace(/'/g,'')}')">📅 Захиалах</button>
        <button class="btn btn-ghost" type="button" onclick="shareIdea('${d.title.replace(/'/g,'').replace(/"/g,'')}')">🔗 Хуваалцах</button>
      </div>
    </div>`;
  document.getElementById("modal").classList.add("show");
}

